import{i as e,r as t,s as n,t as r}from"./app-CSY-Kgjv.js";var i=JSON.parse(`{"path":"/mathph/computer/salg/ecc/ecdh.html","title":"ECDH","lang":"zh-CN","frontmatter":{"description":"ECDH ECDH（椭圆曲线Diffie-Hellman） ECDH（Elliptic Curve Diffie-Hellman）是基于椭圆曲线的密钥交换协议，用于在不安全的通信环境中安全地交换密钥。它与传统的Diffie-Hellman协议类似，但使用椭圆曲线来提供更高的安全性和更小的密钥长度。 1. 选择椭圆曲线和生成公私钥对 选择一个椭圆曲线的参...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"ECDH\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-10-01T02:58:36.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"DeeLMind\\",\\"url\\":\\"https://deelmind.com\\"}]}"],["meta",{"property":"og:url","content":"https://deelmind.com/mathph/computer/salg/ecc/ecdh.html"}],["meta",{"property":"og:site_name","content":"極客方舟"}],["meta",{"property":"og:title","content":"ECDH"}],["meta",{"property":"og:description","content":"ECDH ECDH（椭圆曲线Diffie-Hellman） ECDH（Elliptic Curve Diffie-Hellman）是基于椭圆曲线的密钥交换协议，用于在不安全的通信环境中安全地交换密钥。它与传统的Diffie-Hellman协议类似，但使用椭圆曲线来提供更高的安全性和更小的密钥长度。 1. 选择椭圆曲线和生成公私钥对 选择一个椭圆曲线的参..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-01T02:58:36.000Z"}],["meta",{"property":"article:modified_time","content":"2026-10-01T02:58:36.000Z"}]]},"git":{"createdTime":1790823516000,"updatedTime":1790823516000,"contributors":[{"name":"DeeLMind","username":"DeeLMind","email":"deelmind@DeeLMinds-MacBook-Air.local","commits":1,"url":"https://github.com/DeeLMind"}]},"readingTime":{"minutes":6.56,"words":1969},"filePathRelative":"mathph/computer/salg/ecc/ecdh.md","autoDesc":true}`),a={name:`ecdh.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="ecdh" tabindex="-1"><a class="header-anchor" href="#ecdh"><span>ECDH</span></a></h1><h2 id="ecdh-椭圆曲线diffie-hellman" tabindex="-1"><a class="header-anchor" href="#ecdh-椭圆曲线diffie-hellman"><span>ECDH（椭圆曲线Diffie-Hellman）</span></a></h2><p>ECDH（Elliptic Curve Diffie-Hellman）是基于椭圆曲线的密钥交换协议，用于在不安全的通信环境中安全地交换密钥。它与传统的Diffie-Hellman协议类似，但使用椭圆曲线来提供更高的安全性和更小的密钥长度。</p><h3 id="_1-选择椭圆曲线和生成公私钥对" tabindex="-1"><a class="header-anchor" href="#_1-选择椭圆曲线和生成公私钥对"><span>1. 选择椭圆曲线和生成公私钥对</span></a></h3><p>选择一个椭圆曲线的参数，包括基点 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>G</mi></mrow><annotation encoding="application/x-tex">G</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">G</span></span></span></span> 和曲线的阶 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>n</mi></mrow><annotation encoding="application/x-tex">n</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">n</span></span></span></span>。然后，参与者生成一个私钥（一个随机数），并根据私钥生成公钥。</p><ul><li>假设Alice和Bob使用相同的椭圆曲线和基点 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>G</mi></mrow><annotation encoding="application/x-tex">G</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">G</span></span></span></span>。 <ul><li>Alice选择私钥 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>a</mi></mrow><annotation encoding="application/x-tex">a</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">a</span></span></span></span>，计算公钥 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi><mo>=</mo><mi>a</mi><mi>G</mi></mrow><annotation encoding="application/x-tex">A = aG</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">a</span><span class="mord mathnormal">G</span></span></span></span>。</li><li>Bob选择私钥 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>b</mi></mrow><annotation encoding="application/x-tex">b</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span></span></span></span>，计算公钥 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>B</mi><mo>=</mo><mi>b</mi><mi>G</mi></mrow><annotation encoding="application/x-tex">B = bG</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span><span class="mord mathnormal">G</span></span></span></span>。</li></ul></li></ul><h3 id="_2-交换公钥" tabindex="-1"><a class="header-anchor" href="#_2-交换公钥"><span>2. 交换公钥</span></a></h3><ul><li>Alice将她的公钥 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi></mrow><annotation encoding="application/x-tex">A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span> 发送给Bob。</li><li>Bob将他的公钥 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>B</mi></mrow><annotation encoding="application/x-tex">B</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span> 发送给Alice。</li></ul><h3 id="_3-计算共享密钥" tabindex="-1"><a class="header-anchor" href="#_3-计算共享密钥"><span>3. 计算共享密钥</span></a></h3><ul><li>Alice使用她的私钥 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>a</mi></mrow><annotation encoding="application/x-tex">a</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">a</span></span></span></span> 和收到的Bob的公钥 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>B</mi></mrow><annotation encoding="application/x-tex">B</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span> 来计算共享密钥：<p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>S</mi><mtext>Alice</mtext></msub><mo>=</mo><mi>a</mi><mi>B</mi><mo>=</mo><mi>a</mi><mo stretchy="false">(</mo><mi>b</mi><mi>G</mi><mo stretchy="false">)</mo><mo>=</mo><mo stretchy="false">(</mo><mi>a</mi><mi>b</mi><mo stretchy="false">)</mo><mi>G</mi></mrow><annotation encoding="application/x-tex"> S_{\\text{Alice}} = aB = a(bG) = (ab)G </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">Alice</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">a</span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">a</span><span class="mopen">(</span><span class="mord mathnormal">b</span><span class="mord mathnormal">G</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">ab</span><span class="mclose">)</span><span class="mord mathnormal">G</span></span></span></span></span></p></li><li>Bob使用他的私钥 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>b</mi></mrow><annotation encoding="application/x-tex">b</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span></span></span></span> 和收到的Alice的公钥 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi></mrow><annotation encoding="application/x-tex">A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span> 来计算共享密钥：<p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>S</mi><mtext>Bob</mtext></msub><mo>=</mo><mi>b</mi><mi>A</mi><mo>=</mo><mi>b</mi><mo stretchy="false">(</mo><mi>a</mi><mi>G</mi><mo stretchy="false">)</mo><mo>=</mo><mo stretchy="false">(</mo><mi>a</mi><mi>b</mi><mo stretchy="false">)</mo><mi>G</mi></mrow><annotation encoding="application/x-tex"> S_{\\text{Bob}} = bA = b(aG) = (ab)G </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">Bob</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span><span class="mord mathnormal">A</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">b</span><span class="mopen">(</span><span class="mord mathnormal">a</span><span class="mord mathnormal">G</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">ab</span><span class="mclose">)</span><span class="mord mathnormal">G</span></span></span></span></span></p></li></ul><p>由于 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>a</mi><mi>G</mi></mrow><annotation encoding="application/x-tex">aG</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">a</span><span class="mord mathnormal">G</span></span></span></span> 和 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>b</mi><mi>G</mi></mrow><annotation encoding="application/x-tex">bG</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span><span class="mord mathnormal">G</span></span></span></span> 是通过椭圆曲线计算得到的，所以 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo stretchy="false">(</mo><mi>a</mi><mi>b</mi><mo stretchy="false">)</mo><mi>G</mi></mrow><annotation encoding="application/x-tex">(ab)G</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">ab</span><span class="mclose">)</span><span class="mord mathnormal">G</span></span></span></span> 对于Alice和Bob来说是相同的，最终他们得到了相同的共享密钥。</p><h3 id="_4-共享密钥的使用" tabindex="-1"><a class="header-anchor" href="#_4-共享密钥的使用"><span>4. 共享密钥的使用</span></a></h3><p>生成的共享密钥 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>S</mi></mrow><annotation encoding="application/x-tex">S</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0576em;">S</span></span></span></span> 可用于加密后续通信。</p><h2 id="ecdh的安全性" tabindex="-1"><a class="header-anchor" href="#ecdh的安全性"><span>ECDH的安全性</span></a></h2><p>ECDH的安全性依赖于椭圆曲线离散对数问题（ECDLP）。即使攻击者窃取了交换的公钥，他们也无法反推出私钥或共享密钥。</p><h2 id="举个简单的例子" tabindex="-1"><a class="header-anchor" href="#举个简单的例子"><span>举个简单的例子</span></a></h2><p>假设Alice和Bob要进行ECDH密钥交换，使用一个简单的椭圆曲线和基点 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>G</mi></mrow><annotation encoding="application/x-tex">G</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">G</span></span></span></span>，私钥选择为小整数。</p><h3 id="_1-选择椭圆曲线和基点" tabindex="-1"><a class="header-anchor" href="#_1-选择椭圆曲线和基点"><span>1. 选择椭圆曲线和基点</span></a></h3><p>假设选择的椭圆曲线为 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>y</mi><mn>2</mn></msup><mo>=</mo><msup><mi>x</mi><mn>3</mn></msup><mo>+</mo><mi>a</mi><mi>x</mi><mo>+</mo><mi>b</mi></mrow><annotation encoding="application/x-tex">y^2 = x^3 + ax + b</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:1.0085em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight">2</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8974em;vertical-align:-0.0833em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight">3</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">a</span><span class="mord mathnormal">x</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span></span></span></span>，且基点 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>G</mi></mrow><annotation encoding="application/x-tex">G</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">G</span></span></span></span> 是给定的。</p><h3 id="_2-alice和bob生成私钥和公钥" tabindex="-1"><a class="header-anchor" href="#_2-alice和bob生成私钥和公钥"><span>2. Alice和Bob生成私钥和公钥</span></a></h3><ul><li>Alice的私钥 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>a</mi><mo>=</mo><mn>5</mn></mrow><annotation encoding="application/x-tex">a = 5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.4306em;"></span><span class="mord mathnormal">a</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">5</span></span></span></span>，计算公钥 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi><mo>=</mo><mi>a</mi><mi>G</mi><mo>=</mo><mn>5</mn><mi>G</mi></mrow><annotation encoding="application/x-tex">A = aG = 5G</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">a</span><span class="mord mathnormal">G</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord">5</span><span class="mord mathnormal">G</span></span></span></span>。</li><li>Bob的私钥 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>b</mi><mo>=</mo><mn>7</mn></mrow><annotation encoding="application/x-tex">b = 7</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">7</span></span></span></span>，计算公钥 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>B</mi><mo>=</mo><mi>b</mi><mi>G</mi><mo>=</mo><mn>7</mn><mi>G</mi></mrow><annotation encoding="application/x-tex">B = bG = 7G</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span><span class="mord mathnormal">G</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord">7</span><span class="mord mathnormal">G</span></span></span></span>。</li></ul><h3 id="_3-交换公钥" tabindex="-1"><a class="header-anchor" href="#_3-交换公钥"><span>3. 交换公钥</span></a></h3><ul><li>Alice将公钥 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi><mo>=</mo><mn>5</mn><mi>G</mi></mrow><annotation encoding="application/x-tex">A = 5G</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord">5</span><span class="mord mathnormal">G</span></span></span></span> 发送给Bob，Bob将公钥 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>B</mi><mo>=</mo><mn>7</mn><mi>G</mi></mrow><annotation encoding="application/x-tex">B = 7G</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord">7</span><span class="mord mathnormal">G</span></span></span></span> 发送给Alice。</li></ul><h3 id="_4-计算共享密钥" tabindex="-1"><a class="header-anchor" href="#_4-计算共享密钥"><span>4. 计算共享密钥</span></a></h3><ul><li>Alice计算共享密钥：<p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>S</mi><mtext>Alice</mtext></msub><mo>=</mo><mi>a</mi><mi>B</mi><mo>=</mo><mn>5</mn><mo>×</mo><mo stretchy="false">(</mo><mn>7</mn><mi>G</mi><mo stretchy="false">)</mo><mo>=</mo><mn>35</mn><mi>G</mi></mrow><annotation encoding="application/x-tex"> S_{\\text{Alice}} = aB = 5 \\times (7G) = 35G </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">Alice</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord mathnormal">a</span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">7</span><span class="mord mathnormal">G</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord">35</span><span class="mord mathnormal">G</span></span></span></span></span></p></li><li>Bob计算共享密钥：<p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><msub><mi>S</mi><mtext>Bob</mtext></msub><mo>=</mo><mi>b</mi><mi>A</mi><mo>=</mo><mn>7</mn><mo>×</mo><mo stretchy="false">(</mo><mn>5</mn><mi>G</mi><mo stretchy="false">)</mo><mo>=</mo><mn>35</mn><mi>G</mi></mrow><annotation encoding="application/x-tex"> S_{\\text{Bob}} = bA = 7 \\times (5G) = 35G </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0576em;">S</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0576em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">Bob</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord mathnormal">b</span><span class="mord mathnormal">A</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">7</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">5</span><span class="mord mathnormal">G</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord">35</span><span class="mord mathnormal">G</span></span></span></span></span></p></li></ul><p>由于Alice和Bob的计算过程得到了相同的点 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>35</mn><mi>G</mi></mrow><annotation encoding="application/x-tex">35G</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord">35</span><span class="mord mathnormal">G</span></span></span></span>，因此他们得到了相同的共享密钥。</p><h2 id="椭圆曲线加密算法的安全性" tabindex="-1"><a class="header-anchor" href="#椭圆曲线加密算法的安全性"><span>椭圆曲线加密算法的安全性</span></a></h2><p>椭圆曲线加密算法（ECC，Elliptic Curve Cryptography）的安全性主要依赖于 <strong>椭圆曲线离散对数问题（ECDLP）</strong>，它是一种非常困难的数学问题。ECC在保证高安全性的同时，使用相对较短的密钥长度，这使得它在现代加密系统中非常有优势。以下是椭圆曲线加密算法的安全性分析：</p><h3 id="_1-椭圆曲线离散对数问题-ecdlp" tabindex="-1"><a class="header-anchor" href="#_1-椭圆曲线离散对数问题-ecdlp"><span>1. 椭圆曲线离散对数问题（ECDLP）</span></a></h3><p>ECC的安全性基于椭圆曲线离散对数问题。具体来说，给定椭圆曲线上的基点 G 和某点 P = kG，其中 k 是一个私钥（整数），问题是从 G 和 P 中计算出 k（即求解离散对数）。这个问题被认为是 <strong>困难的</strong>，且当前没有有效的多项式时间算法来解决这个问题。</p><ul><li><strong>ECDLP的难度</strong>：在有限域上求解离散对数问题的难度是目前已知的最强的密码学假设之一。通过计算椭圆曲线上的点乘 kG 和离散对数问题，我们无法在多项式时间内推算出私钥 k，这确保了椭圆曲线加密算法的安全性。</li></ul><h2 id="_2-安全性与密钥长度" tabindex="-1"><a class="header-anchor" href="#_2-安全性与密钥长度"><span>2. 安全性与密钥长度</span></a></h2><p>椭圆曲线加密算法提供了相对于其他加密算法（如RSA）更高的安全性，且密钥长度较短。例如：</p><ul><li><strong>256位的椭圆曲线密钥</strong>提供的安全性相当于<strong>3072位的RSA密钥</strong>。</li><li><strong>384位的椭圆曲线密钥</strong>提供的安全性相当于<strong>7680位的RSA密钥</strong>。</li><li><strong>521位的椭圆曲线密钥</strong>提供的安全性相当于<strong>15360位的RSA密钥</strong>。</li></ul><p>椭圆曲线的高效性意味着使用较短的密钥就可以达到和传统加密算法相同的安全级别，这对于需要高效计算的环境（如移动设备、物联网设备等）尤其重要。</p><h2 id="_3-抗量子计算的安全性" tabindex="-1"><a class="header-anchor" href="#_3-抗量子计算的安全性"><span>3. 抗量子计算的安全性</span></a></h2><p>尽管目前没有有效的量子计算机可用于破解ECC，但根据量子计算的发展趋势，<strong>Shor算法</strong>（量子算法）能够在多项式时间内破解基于大数因式分解的RSA和基于离散对数的DH（Diffie-Hellman）算法，这意味着量子计算可能威胁到这些传统加密算法的安全性。</p><p>然而，椭圆曲线加密本身也受量子计算威胁，因为Shor算法也能够在量子计算机上解决椭圆曲线离散对数问题。因此，虽然目前ECC非常安全，但它仍然不具备量子抗性。</p><h2 id="_4-曲线选择和参数的安全性" tabindex="-1"><a class="header-anchor" href="#_4-曲线选择和参数的安全性"><span>4. 曲线选择和参数的安全性</span></a></h2><p>椭圆曲线加密的安全性不仅仅取决于ECDLP问题的困难性，还与曲线的选择和相关参数有关。使用不合适或已知存在漏洞的曲线（例如，具有特定结构的曲线）可能使得ECC的安全性受到威胁。例如：</p><ul><li><strong>NIST推荐曲线</strong>：一些被广泛使用的标准曲线，如NIST（美国国家标准与技术研究院）推荐的P-192、P-256、P-384和P-521曲线，这些曲线已经经过了广泛的安全性验证。</li><li><strong>Curve25519和Ed25519</strong>：这些是由Daniel J. Bernstein提出的曲线，广泛认为在现代密码学中具有非常高的安全性和性能，特别是在对抗侧信道攻击方面表现优异。</li></ul><p>选择合适的椭圆曲线和安全的参数非常重要，因为曲线上的特殊结构或参数选择不当可能导致弱点，从而使得加密算法容易被破解。</p><h2 id="_5-侧信道攻击防护" tabindex="-1"><a class="header-anchor" href="#_5-侧信道攻击防护"><span>5. 侧信道攻击防护</span></a></h2><p>椭圆曲线加密算法需要特别注意 <strong>侧信道攻击</strong>（如时序攻击、功耗分析等），这些攻击通过分析加密过程中的物理特征（如计算时间、电磁波、功耗等）来推算出密钥。为了防止这些攻击，需要使用 <strong>防侧信道</strong> 技术（如随机化加密过程、加密算法优化等）来加强ECC实现的安全性。</p><h2 id="_6-已知的攻击方法" tabindex="-1"><a class="header-anchor" href="#_6-已知的攻击方法"><span>6. 已知的攻击方法</span></a></h2><p>尽管ECDLP被认为是一个非常困难的问题，但也有一些已知的攻击方法，主要是通过数学和计算技术来攻击ECC：</p><ul><li><strong>碰撞攻击</strong>：这类攻击尝试在有限域内找到两个不同的点，其对应的结果在某些条件下可以使得解密过程失败。但在现代的椭圆曲线设计中，这类攻击非常困难。</li><li><strong>畸变攻击</strong>：这是一种利用椭圆曲线的某些数学性质来破解加密的攻击方式。然而，如果选择的曲线是安全的，这类攻击的成功几率非常低。</li></ul><h2 id="_7-ecc的优势" tabindex="-1"><a class="header-anchor" href="#_7-ecc的优势"><span>7. ECC的优势</span></a></h2><ul><li><strong>高效性</strong>：ECC相对于RSA等算法具有更短的密钥长度，且计算效率更高。相同安全级别下，ECC的计算要求和带宽消耗都比传统算法低得多。</li><li><strong>节省存储空间</strong>：由于密钥长度较短，ECC能够在存储有限的设备上运行，如嵌入式设备、移动设备等。</li><li><strong>广泛应用</strong>：ECC已广泛应用于各种现代加密协议和技术中，如SSL/TLS协议、数字签名（ECDSA）、密钥交换（ECDH）等。</li></ul>`,49)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};